const BASE="/api/tp07/v2",PARTNER_TOKEN="pt_4d1f7a0c93e2b856";function role(){return localStorage.getItem("portal_role")||"partner"}function headers(t){return Object.assign({"X-User-Role":role()},t||{})}async function getJson(t,n){return(await fetch(BASE+t,{headers:headers(n)})).json()}async function exportAll(){return getJson("/internal/export")}async function init(){const t=await getJson("/status");document.getElementById("status").textContent="Plateforme : "+t.platform,role()==="admin"&&(document.getElementById("admin").style.display="block")}document.getElementById("btn-invoices").addEventListener("click",async()=>{const t=await getJson("/invoices",{"X-Partner-Token":PARTNER_TOKEN});document.getElementById("invoices").textContent=JSON.stringify(t,null,2)}),document.getElementById("btn-settings").addEventListener("click",async()=>{const t=await getJson("/admin/settings");document.getElementById("settings").textContent=JSON.stringify(t,null,2)}),window.__debugExport=exportAll,init();
